 internal void Write(string phase,object data){Log.Write(phase,data);ObserveDiagnosticEvent(phase,data);string text=phase;if(phase=="ui-state"){var d=Common.Json.Deserialize<Dictionary<string,object>>(Common.Json.Serialize(data));text=Common.S(d,"title")+"："+Common.S(d,"message");}history.AppendText(DateTime.Now.ToString("HH:mm:ss")+"  "+text+Environment.NewLine);if(history.TextLength>32768){string v=history.Text;int cut=v.IndexOf('\n',v.Length-24576);history.Text=v.Substring(cut<0?v.Length-24576:cut+1);}historyRevision++;}
