 void RefreshCards(){cards.SuspendLayout();while(cards.Controls.Count>0)cards.Controls[0].Dispose();count.Text="我的壁纸  ·  "+library.Doc.Items.Count;foreach(var item in library.Doc.Items){var card=new WallpaperCard(item,library.Status(item)){Font=Font,Selected=selected!=null&&selected.Id==item.Id};card.Chosen+=(s,e)=>SelectWallpaper(card.Item);cards.Controls.Add(card);}cards.ResumeLayout();LayoutCards();RefreshSelection();RefreshEmptyState();if(library.Error!=null){libraryHint.Text=library.Error;libraryHint.ForeColor=Color.Firebrick;}else RefreshRuntimeNotice();}
