  string reason=operationBusy?"当前操作尚未结束":selected==null?"请先选择壁纸":!File.Exists(selected.SourcePath)?"文件不存在，已保留登记，请恢复原文件位置。":library.FormatError(selected)??"所选文件暂时不可读取，请查看详情。";
  bool recovery=CurrentRun!=null&&!Clean&&(WorkerRole=="exited"||State.Contains("unconfirmed")||State=="stop-timeout");
  var actions=PlaybackActions.For(PlaybackPermitted,runtimeCheckRunning,selected!=null,supported,!operationBusy&&selected!=null&&library.IsPreviewConfirmedHint(selected),playbackPreparation.Busy,playbackPreparation.UserCancelled&&playbackPreparation.Busy,operationBusy,closing,CurrentRun!=null&&!Clean,recovery,reason);
  preview.Enabled=actions.Preview;desktop.Enabled=actions.Desktop;stop.Enabled=actions.Stop;
  preview.AccessibleDescription=actions.Reason;desktop.AccessibleDescription=actions.Reason;
  selectedNote.Text=MultiWallpaperPresentation.Selection(selected==null?null:selected.Id,activeRunRequest==null?null:Common.S(activeRunRequest,"selectedCatalogId"),activeRunName,PlayerRole=="alive",actions.Reason);selectedNote.ForeColor=supported&&RuntimeProvisioning.Available?Muted:Color.FromArgb(157,82,28);
