 internal void AcceptAddedFile(string path){try{bool duplicate;var item=library.Add(path,out duplicate);selected=item;Cwp=item.SourcePath;libraryHint.Text=duplicate?"这个文件已登记，已选中原卡片。":"已添加为未验证；没有启动或应用壁纸。";RefreshCards();Write("catalog-added",new{id=item.Id,source=item.SourcePath,duplicate=duplicate,status=library.Status(item),autoPlayed=false});}catch(Exception ex){libraryHint.Text=ex.Message;libraryHint.ForeColor=Color.Firebrick;Write("catalog-error",new{error=ex.ToString()});}}
